import{_ as o,o as t,c as d,a1 as c}from"./chunks/framework.BKrM4vFX.js";const p=JSON.parse('{"title":"kontur-ofd-mock — Контур.ОФД, read/reconciliation","description":"kontur-ofd-mock — Контур.ОФД, read/reconciliation. © 2026 ООО «Аксиома» ИНН:7842223709 · https://github.com/rucorp/mock-services · все права защищены Документ проекта mock-services (оригинал: rucorp/mock-services). SPDX-License-Identifier: Apache-2.0 Девятый сервис стенд","frontmatter":{"sourcePath":"services/kontur-ofd-mock/README.md"},"headers":[{"level":1,"title":"kontur-ofd-mock — Контур.ОФД, read/reconciliation","slug":"kontur-ofd-mock-КонтурОФД-readreconciliation","link":"#kontur-ofd-mock-КонтурОФД-readreconciliation","children":[{"level":2,"title":"Запуск","slug":"Запуск","link":"#Запуск","children":[]},{"level":2,"title":"Контракт","slug":"Контракт","link":"#Контракт","children":[]},{"level":2,"title":"Env","slug":"env","link":"#env","children":[]},{"level":2,"title":"Сценарии и ограничения","slug":"Сценарии-и-ограничения","link":"#Сценарии-и-ограничения","children":[]},{"level":2,"title":"Байтовые квоты состояния (PD-02)","slug":"Байтовые-квоты-состояния-pd-02","link":"#Байтовые-квоты-состояния-pd-02","children":[]}]}],"relativePath":"services/kontur-ofd-mock/README.md","filePath":"services/kontur-ofd-mock/README.md"}'),a={name:"services/kontur-ofd-mock/README.md"};function r(s,e,i,n,l,_){return t(),d("div",null,[...e[0]||(e[0]=[c(`<p>© 2026 ООО «Аксиома» ИНН:7842223709 · <a href="https://github.com/rucorp/mock-services" target="_blank" rel="noreferrer">https://github.com/rucorp/mock-services</a> · все права защищены Документ проекта mock-services (оригинал: rucorp/mock-services). SPDX-License-Identifier: Apache-2.0</p><h1 id="kontur-ofd-mock-КонтурОФД-readreconciliation" tabindex="-1">kontur-ofd-mock — Контур.ОФД, read/reconciliation <a class="header-anchor" href="#kontur-ofd-mock-КонтурОФД-readreconciliation" aria-label="Permalink to &quot;kontur-ofd-mock — Контур.ОФД, read/reconciliation&quot;">​</a></h1><nav class="doc-static-toc" aria-label="Оглавление"><p class="doc-static-toc__title">Оглавление</p><ul><li class="doc-static-toc__item doc-static-toc__item--1"><a class="doc-static-toc__link" href="#kontur-ofd-mock-КонтурОФД-readreconciliation">kontur-ofd-mock — Контур.ОФД, read/reconciliation</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Запуск">Запуск</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Контракт">Контракт</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#env">Env</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Сценарии-и-ограничения">Сценарии и ограничения</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Байтовые-квоты-состояния-pd-02">Байтовые квоты состояния (PD-02)</a></li></ul></nav><p>Девятый сервис стенда, касса/ОФД №4, issue #97. <strong>Только чтение</strong> уже фискализированных документов: это не очередь печати, не Ferma и не OKassa. Node ≥18, CommonJS, zero dependencies, общее ядро <code>packages/core</code> не изменено.</p><p>Источник (2026-10-11): официальная документация Контур.ОФД (auth/access, документы). <a href="./../../docs/integration/kontur-ofd">Рецепт интеграции, curl, сценарии и полный список <code>[FORK]</code></a>, <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/kontur-ofd-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a>, <a href="https://github.com/rucorp/mock-services/blob/main/protocols/kontur-ofd.json" target="_blank" rel="noreferrer">drift-манифест</a>.</p><h2 id="Запуск" tabindex="-1">Запуск <a class="header-anchor" href="#Запуск" aria-label="Permalink to &quot;Запуск&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Сначала задайте синтетические env по рецепту интеграции (см. ссылку выше).</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:kontur-ofd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # :3108</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:kontur-ofd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # HTTP selftest на :0, без Docker</span></span></code></pre></div><p>Дефолтных login/password/API key <strong>нет</strong>. Без env default-auth закрыт; в owned-песочнице реквизиты генерируются при <code>POST /sandboxes</code>. Это <code>[FORK]</code>: публичных статических тестовых кредов провайдера нет, выданные ему реквизиты не коммитить и не использовать на mock-стенде.</p><p>Docker: <code>docker build -t mock-services:kontur-local .</code>, затем <code>MOCK_IMAGE=mock-services MOCK_IMAGE_TAG=kontur-local MOCK_IMAGE_DIGEST=&#39;&#39; docker compose -f docker-compose.include.yml --profile mock up -d kontur-ofd-mock</code>. Старый pinned GHCR-релиз 0.6.0 <strong>не содержит новый сервис</strong>; образ и pin публикует владелец отдельно. Корневой <code>docker-compose.yml</code> намеренно не меняется.</p><h2 id="Контракт" tabindex="-1">Контракт <a class="header-anchor" href="#Контракт" aria-label="Permalink to &quot;Контракт&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Метод</th><th>Назначение</th></tr></thead><tbody><tr><td><code>POST /auth/authenticate-by-pass?login=&lt;email&gt;</code></td><td>UTF-8 plaintext password в body → <code>{Sid}</code></td></tr><tr><td><code>GET /v2/organizations</code></td><td>доступные организации</td></tr><tr><td><code>GET /v2/organizations/{organizationId}/cashboxes</code></td><td>кассы, regNumber, модель/ФН, адреса, период доступа</td></tr><tr><td><code>GET .../cashboxes/{kktRegId}/documents?date=YYYY-MM-DD&amp;types=...</code></td><td>массив документов за день</td></tr><tr><td><code>GET .../documents/by-period?dateFrom=...&amp;dateTo=...&amp;offset=0&amp;limit=1000</code></td><td><code>{documents[],paging.nextOffset}</code></td></tr><tr><td><code>GET .../documents/{documentId}</code></td><td>отдельный документ</td></tr><tr><td><code>GET /health</code>, <code>GET /openapi.json</code></td><td>healthcheck, OpenAPI 3.1</td></tr><tr><td><code>GET /admin</code>, <code>GET /admin/journal</code></td><td>read-only консоль, журнал без секретов</td></tr><tr><td><code>/mock/time</code>, <code>/mock/state</code>, <code>/mock/reset</code>, <code>/mock/scenarios</code></td><td>часы, fixtures, reset, сценарии</td></tr><tr><td><code>/sandboxes</code>, <code>/sandboxes/me</code>, <code>/sandboxes/me/reset</code>, <code>/sandboxes/me/reset-creds</code>, <code>/mock/sandboxes</code></td><td>стандартный sandbox control plane</td></tr></tbody></table><p>Все <code>/v2/...</code> требуют <code>Authorization: auth.sid &lt;Sid&gt;</code> <strong>и</strong><code>X-Kontur-Ofd-ApiKey</code>. Sid живёт 30 дней на виртуальных часах; при отсутствии, истечении/отзыве → 401 <code>errorCodeId=401002</code>. Пропущенный/неизвестный ключ → 401 <code>401003</code>. При ошибках ориентироваться на <code>errorCodeId</code>, не на устаревшее <code>errorCode</code>. Неправильные даты/параметры: 400; нет согласия: 403; неизвестный объект: 404; <code>fail</code>: 500. Пустой период → 200, пустой список.</p><p>Документы: все 10 типов из среза; суммы <strong>в целых копейках</strong>; в receipt <code>items</code>, <code>operationType</code>, <code>fiscalDocumentNumber</code>, <code>fiscalSign</code>, <code>id</code>. Демо-каталог каждой песочницы: <code>org-demo</code>, касса <code>0000000000000001</code>, 12 ФД за <strong>2026-10-11</strong>, включая три receipt, один из них возврат. Демо не меняется от виртуального времени. Фикстуры синтетические, имена неполностью раскрытых полей и FFD-операции — <code>[FORK]</code>.</p><p><strong>[FORK] offset/currentOffset:</strong> каноничен <code>offset</code>, <code>currentOffset</code> даёт 400 с подсказкой; <code>nextOffset=null</code> завершает обход. Выбор согласован с владельцем до кода по URL-примерам и подтверждён <strong>локальной</strong> OpenAPI/selftest; подтверждение тестовой схемой провайдера <strong>не получено</strong>. Предел страницы — 1000. UTC без timezone и включённые обе границы периода — <code>[FORK]</code>.</p><h2 id="env" tabindex="-1">Env <a class="header-anchor" href="#env" aria-label="Permalink to &quot;Env&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Переменная</th><th>Дефолт / назначение</th></tr></thead><tbody><tr><td><code>MOCK_HOST</code>, <code>MOCK_PORT</code></td><td><code>0.0.0.0</code>, <code>3108</code>; bind/порт сервера</td></tr><tr><td><code>MOCK_HEALTH_PATH</code></td><td><code>/health</code> в include; используется Docker healthcheck, маршрут сервиса фиксирован</td></tr><tr><td><code>MOCK_KONTUR_OFD_LOGIN</code></td><td>пусто; синтетический email default-песочницы</td></tr><tr><td><code>MOCK_KONTUR_OFD_PASSWORD</code></td><td>пусто; UTF-8 plaintext password, не выводится в лог</td></tr><tr><td><code>MOCK_KONTUR_OFD_API_KEY</code></td><td>пусто; дополнительный ключ data API, не выводится в лог</td></tr><tr><td><code>MOCK_KONTUR_OFD_SID_TTL_SECS</code></td><td><code>2592000</code>; целые секунды 1..31536000 на виртуальных часах</td></tr><tr><td><code>MOCK_KONTUR_OFD_PUBLIC_BASE_URL</code></td><td><code>http://localhost:\${MOCK_KONTUR_OFD_HOST_PORT:-3108}</code>; публичная база provisioning-ссылок</td></tr><tr><td><code>MOCK_VIRTUAL_CLOCK</code></td><td>пусто → текущее время; ISO начальных виртуальных часов</td></tr><tr><td><code>MOCK_HOSTED</code></td><td><code>false</code>; hosted fail-closed для control endpoints</td></tr><tr><td><code>MOCK_TENANCY</code></td><td><code>namespaces</code>, при hosted → <code>owned</code>; поддерживается <code>off</code></td></tr><tr><td><code>MOCK_ADMIN_TOKEN</code></td><td>пусто; защита <code>/admin*</code>, также operator access</td></tr><tr><td><code>MOCK_OPERATOR_TOKEN</code></td><td>пусто; защита <code>/mock/*</code></td></tr><tr><td><code>MOCK_SANDBOX_TOKEN</code></td><td>пусто; owner-token default-песочницы; при <code>MOCK_HOSTED=1</code> без него <code>default</code> не обслуживается (MS-12)</td></tr><tr><td><code>MOCK_SANDBOX_TTL_MS</code></td><td>owned: <code>86400000</code>, иначе <code>0</code>; wall-clock TTL песочницы</td></tr><tr><td><code>MOCK_SANDBOX_MAX</code></td><td><code>100</code>; максимум именованных песочниц</td></tr><tr><td><code>MOCK_SANDBOX_MAX_DOCUMENTS</code></td><td>owned: <code>5000</code>, иначе <code>0</code>; число ФД + сессий (квота ядра)</td></tr><tr><td><code>MOCK_SANDBOX_HOST_SUFFIX</code></td><td>пусто; host-selector ядра для песочниц</td></tr><tr><td><code>MOCK_SANDBOX_CREATE_LIMIT</code></td><td><code>20</code>; создание owned-песочниц с IP за час, <code>0</code> без лимита</td></tr><tr><td><code>MOCK_SANDBOX_SWEEP_MS</code></td><td><code>60000</code>; интервал wall-clock sweep, unref timer</td></tr><tr><td><code>MOCK_STATE_FILE</code></td><td>пусто; persist default state, compose <code>/data/kontur-ofd-state.json</code></td></tr><tr><td><code>MOCK_SANDBOX_FILE</code></td><td>по ядру из state path; compose <code>/data/kontur-ofd-sandboxes.json</code></td></tr><tr><td><code>MOCK_KONTUR_OFD_BIND_IP</code>, <code>MOCK_KONTUR_OFD_HOST_PORT</code></td><td>include-only: <code>127.0.0.1</code>, <code>3108</code></td></tr><tr><td><code>MOCK_KONTUR_OFD_CADDY_DOMAIN</code></td><td>include-only: пусто; optional reverse proxy label</td></tr></tbody></table><p>В owned запросах добавляйте <code>X-Mock-Sandbox</code> + <code>X-Sandbox-Token</code> <strong>наряду с</strong><code>Authorization: auth.sid ...</code> и API key. Чужие токены и знание ID не дают прав. Control token в hosted обязателен; оператор может управлять песочницами, владелец — только своей. Reset/state import/rotation отзывают Sid; экспорт <code>/mock/state</code> не раскрывает Sid, <code>/sandboxes/me</code> не раскрывает креды. Persist files содержат mock-сессии/креды; защищайте volume и не храните реальные чеки/ПДн. <a href="./../../SECURITY">Модель угроз</a>.</p><h2 id="Сценарии-и-ограничения" tabindex="-1">Сценарии и ограничения <a class="header-anchor" href="#Сценарии-и-ограничения" aria-label="Permalink to &quot;Сценарии и ограничения&quot;">​</a></h2><p><code>X-Mock-Scenario: fail|hang|duplicate|latency:200ms|http-500|http-504</code>. В <code>POST /mock/scenarios</code> доступны <code>target: auth|read|*</code>, <code>times</code>, <code>persistent</code>, <code>match</code>; сценарии и журнал изолированы по песочницам. <code>duplicate</code> повторяет тот же ФД перед пагинацией, не создаёт чек. <code>hang</code> завершается закрытием соединения клиентом. Виртуальное время двигается <code>POST /mock/time</code>.</p><p><strong>Не моделируется:</strong> создание/фискализация чека, запуск возврата, callback печати, очередь статусов, Cookie auth.sid, статистика, сложная история согласий и фильтрация по их периодам. Объединение двух удалённых hosts в один локальный сервис, numeric cursor/null, fixture-envelope, UTC, повторные Sid, error messages и сценарии — явно документированные <code>[FORK]</code>, не гарантия провайдера. Проверка реального тестового контура/закрытой схемы не выполнена.</p><h2 id="Байтовые-квоты-состояния-pd-02" tabindex="-1">Байтовые квоты состояния (PD-02) <a class="header-anchor" href="#Байтовые-квоты-состояния-pd-02" aria-label="Permalink to &quot;Байтовые квоты состояния (PD-02)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Env</th><th>Дефолт</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_SANDBOX_MAX_STATE_BYTES</code></td><td>пусто: <code>8388608</code> (8 МиБ) при <code>maxDocuments &gt; 0</code>, иначе без лимита</td><td>байты JSON одной песочницы; <code>0</code> выключает</td></tr><tr><td><code>MOCK_SANDBOX_GLOBAL_MAX_STATE_BYTES</code></td><td><code>67108864</code> (64 МиБ)</td><td>сумма байт JSON всех песочниц рантайма, включая <code>default</code>; <code>0</code> выключает</td></tr></tbody></table><p>Значения задаются в целых байтах. Пусто сохраняет дефолты. Квота per-sandbox не ограничивает память контейнера; общий бюджет меньше <code>mem_limit: 128m</code>, но не равен RSS. Превышение глобального бюджета на записи или байтовых квот при импорте <code>/mock/state</code> → HTTP 400, <code>errorCode: 400</code>, <code>kind: &#39;bytes&#39;</code>, <code>code: sandbox_state_budget_exceeded</code> / <code>sandbox_state_quota_exceeded</code>, с откатом отклонённого состояния. Правила/история/журнал остаются volatile. Подробности и границы — <a href="./../../packages/core/README#байтовые-квоты-песочниц-pd-02-74">документация ядра</a>.</p>`,23)])])}const k=o(a,[["render",r]]);export{p as __pageData,k as default};
